"""Root's masked full-context reading of20 ToxiGen audit records."""
from pathlib import Path
import json,hashlib
A=Path(__file__).resolve().parent
p=A/'packets/context_toxigen.jsonl';rows=[json.loads(l) for l in p.read_text().splitlines()]
# Manual semantic judgments after reading both complete messages and full rationale.
data=[
('C','CONTEXT,INTENT','R','P','misreads_text','consistent',['unsupported_target_inference'],'by implying that sharks would target them','target','its fins are missing','Reverses who harms whom: the missing fins suggest harm to the shark, not the shark targeting Asians. The racial-stereotype criterion itself fits the task.'),
('N','CONTEXT,SEVERITY','T','N','supported','unclear',['uncertain'],'while potentially tasteless or edgy, it does not rise to the level','target','turning Stephen Hawking off and on again','Acknowledges the disability/equipment joke. Whether this mockery exceeds the toxicity boundary is a contestable convention, not a demonstrated factual misreading.'),
('N','CONTEXT,FACT','T','N','unsupported_inference','unclear',['uncertain'],'a factual observation about the UK in relation to other Arabic countries','target','the only arabic country','Treats the deliberately incongruous description literally as a factual observation. Possible sarcastic group implication is not assessed; avoid claiming a specific hidden intent.'),
('N','CONTEXT,FACT','T','N','supported','consistent',['none_identified'],'discusses statistical disparities in disciplinary outcomes','target','more likely than their white peers to be suspended','Reports disparity without explicitly endorsing it. This interpretation is supported; truth of the statistic is not independently verified here.'),
('N','CONTEXT,INTENT','T','N','supported','consistent',['none_identified'],'a statement about fear and vulnerability rather than a toxic or hateful expression','target','muslims are scared','Correctly separates reporting religious persecution from expressing hostility.'),
('S','CONTEXT','R','N','supported','consistent',['none_identified'],'The reference example involves a fantasy about marrying a jinn, which is also not toxic in a hateful sense','neighbor','marry a jinn','Treats both as fantastical statements; explicitly declines to infer toxicity from the positive neighbour label. The reference could be read differently but no textual misreading is apparent.'),
('N','INTENT,TOPIC','T','P','supported','consistent',['none_identified'],'a derogatory term often used to shame women for sexual behavior','target','sluttiness is equivalent to attractiveness','Applies the implicit derogatory-stereotype criterion. Alternative reclamation reading is possible but unstated; does not merely follow the neighbour.'),
('S','LABEL,TOPIC','L','U','misreads_text','consistent',['imports_neighbour_facts_or_intent'],'the reference example shows that the probe associates this type of economic stereotyping with the positive class','neighbor','breeding with Blacks','The supplied neighbour concerns interracial reproduction, not economic competition. The proposed economic similarity is unsupported even though the target does discuss labour competition.'),
('N','CONTEXT,INTENT','T','N','supported','consistent',['none_identified'],'The text expresses support for a group','target','examples of healthy diversity','Correctly reads supportive stance despite the opposing negative neighbour.'),
('B','TOPIC,CONTEXT,LABEL','R','N','supported','consistent',['none_identified'],'The similarity is based on a truncated sentence fragment, and the content itself is not derogatory','neighbor','if youre a woman who has sex with women, you','Recognizes incomplete reference and neutral target; identifies probe prediction accurately without equating it with reference gold.'),
('S','LABEL,INTENT','R','P','supported','consistent',['none_identified'],'This aligns with the reference example, which is labeled as toxic','target','too lazy to get up from the couch','Near-verbatim neighbour supplies a convention anchor for the same insulting phrase. Group identity is unspecified; no extra protected group is invented.'),
('N','INTENT,CONTEXT','T','P','supported','consistent',['none_identified'],'characterizing their rehabilitation as a "waste of time and money','target','a waste of time and money to try and rehabilitate someone','Applies implicit derogation to categorical dismissal of institutionalized people; it is an interpretation rather than a demonstrable source error.'),
('C','CONTEXT,INTENT','R','P','unsupported_inference','consistent',['imports_neighbour_facts_or_intent','unsupported_target_inference'],'suggesting that their politeness is unusual or unexpected','target',"they're very polite",'Target describes courteous behaviour; unexpectedness is not stated. The rationale imports negative framing from the contrasting neighbour to turn praise into derogation.'),
('N','INTENT,TOPIC','T','N','supported','criterion_shift',['changes_task_criterion'],'expresses a negative stereotype about disabled people but does not use overtly toxic language','task','including implicit derogatory stereotypes','Acknowledges the negative stereotype yet exempts it for lack of overt hate; this narrows the explicit task definition.'),
('N','CONTEXT,INTENT','T','N','supported','consistent',['none_identified'],'a positive, supportive discussion about an educational tool','target','every teacher should use this game for teaching vocabulary','Grounded benign interpretation; no harmful content inferred from a fragment.'),
('N','CONTEXT,INTENT','T','N','supported','consistent',['none_identified'],'acknowledges that decision-making can be difficult for some people','target','sometimes, they are just unable to make a decision','Qualified difficulty plus parenthetical understanding supports a neutral reading; no demonstrated categorical hateful claim.'),
('C','LABEL,CONTEXT','R','U','supported','unclear',['reference_label_prediction_conflict','uncertain'],'While the reference example was classified as toxic by the probe','neighbor','if you have ever been in the middle east then you will know what i am talking about','Near-identical texts; rationale focuses on the positive probe despite negative neighbour gold, leaves ambiguity at50. No explicit reconciliation of the two supplied class cues.'),
('C','CONTEXT,INTENT','R','N','misreads_text','consistent',['misses_stance_negation_or_role'],'using the bathroom and then leaving','target','He came.','The text does not say he left. Literal paraphrase also overlooks a plausible sexual pun in a disability joke; class correctness remains independently unresolved.'),
('N','INTENT,TOPIC','T','N','supported','criterion_shift',['changes_task_criterion'],'does not use derogatory language, dehumanization, or explicit hate speech','task','including implicit derogatory stereotypes','It acknowledges a negative group judgment but exempts it through explicitness/value-judgment distinction, despite rubric covering implicit content. Degree of derogation remains contestable.'),
('C','CONTEXT,INTENT,SEVERITY','R','P','unsupported_inference','consistent',['unsupported_target_inference'],'implying those who don\'t know their history are complicit or ignorant in a derogatory way','target','the ones who know their history, and the ones who do not','The supplied sentence does not assert complicity or derogatory ignorance. Rationale supplies a hostile implication while comparing with overtly hostile neighbour.')]
assert len(data)==len(rows)==20
out=[]
for row,d in zip(rows,data):
 rel,axes,bridge,conclusion,support,taskrule,flags,rq,side,cq,note=d
 assert rq in row['rationale'],(row['audit_id'],rq)
 source=row['task'] if side=='task' else '\n'.join(m['content'] for m in row['context'][side+'_messages'])
 assert cq in source,(row['audit_id'],cq)
 out.append(dict(audit_id=row['audit_id'],relation=rel,axes=axes.split(','),bridge=bridge,conclusion=conclusion,quality='A',context_support=support,task_rule=taskrule,flags=flags,evidence=[dict(rationale_quote=rq,context_side=side,context_quote=cq,supports=note)],note=note))
dest=A/'codes/root';dest.mkdir(exist_ok=True)
(dest/'toxigen.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in out))
(dest/'toxigen.receipt.json').write_text(json.dumps(dict(reader='/root',n=len(rows),all_contexts_and_rationales_read=True,input_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),coding_version='context-v1',outcomes_masked=True,notes='All20 complete target/neighbour texts and rationales read; task shown on each first10 record then held fixed. No original outcomes or first probability accessed.'),indent=2)+'\n')
print('Validated20 masked full-context assessments')
